import{_ as p,a0 as l,w as u,s as d,ao as o,I as i,x as n,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"如何禁用 Ubuntu 服務器中終端歡迎消息中的廣告 | LCTT x X-CMD","titleTemplate":false,"description":"如何禁用 Ubuntu 服務器中終端歡迎消息中的廣告 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何禁用 Ubuntu 服務器中終端歡迎消息中的廣告 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何禁用 Ubuntu 服務器中終端歡迎消息中的廣告 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20180820 How To Disable Ads In Terminal Welcome Message In Ubuntu Server","title":"如何禁用 Ubuntu 服務器中終端歡迎消息中的廣告","tag":"201811","desc":""},"relativePath":"201811/20180820 How To Disable Ads In Terminal Welcome Message In Ubuntu Server.md","filePath":"[post].md"}'),r={name:"201811/20180820 How To Disable Ads In Terminal Welcome Message In Ubuntu Server.md"};function c(m,s,b,h,g,f){const e=l("Link");return u(),d("div",null,[s[20]||(s[20]=o('<h1 id="如何禁用-ubuntu-服務器中終端歡迎消息中的廣告" tabindex="-1">如何禁用 Ubuntu 服務器中終端歡迎消息中的廣告 <a class="header-anchor" href="#如何禁用-ubuntu-服務器中終端歡迎消息中的廣告" aria-label="Permalink to “如何禁用 Ubuntu 服務器中終端歡迎消息中的廣告”">​</a></h1><p>如果你正在使用最新的 Ubuntu 服務器版本，你可能已經注意到歡迎消息中有一些與 Ubuntu 服務器平台無關的促銷鏈接。你可能已經知道 <strong>MOTD</strong>，即 <strong>M</strong>essage <strong>O</strong>f <strong>T</strong>he <strong>D</strong>ay 的開頭首字母，在 Linux 系統每次登錄時都會顯示歡迎信息。通常，歡迎消息包含操作系統版本，基本系統信息，官方文檔鏈接以及有關最新安全更新等的鏈接。這些是我們每次通過 SSH 或本地登錄時通常會看到的內容。但是，最近在終端歡迎消息中出現了一些其他鏈接。我已經幾次注意到這些鏈接，但我並在意，也從未點擊過。以下是我的 Ubuntu 18.04 LTS 服務器上顯示的終端歡迎消息。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/Ubuntu-Terminal-welcome-message.png" alt=""></p>',3)),i("p",null,[s[2]||(s[2]=n("正如你在上面截圖中所看到的，歡迎消息中有一個 bit.ly 鏈接和 Ubuntu wiki 鏈接。有些人可能會驚訝並想知道這是什麼。其實歡迎信息中的鏈接無需擔心。它可能看起來像廣告，但並不是商業廣告。鏈接實際上指向到了 ",-1)),t(e,{href:"https://blog.ubuntu.com/"},{default:a(()=>[...s[0]||(s[0]=[n("Ubuntu 官方Blog",-1)])]),_:1}),s[3]||(s[3]=n(" 和 ",-1)),t(e,{href:"https://wiki.ubuntu.com/"},{default:a(()=>[...s[1]||(s[1]=[n("Ubuntu wiki",-1)])]),_:1}),s[4]||(s[4]=n("。正如我之前所説，其中的一個鏈接是不相關的，沒有任何與 Ubuntu 服務器相關的細節，這就是為什麼我開頭稱它們為廣告。",-1))]),s[21]||(s[21]=o(`<p>雖然我們大多數人都不會訪問 bit.ly 鏈接，但是有些人可能出於好奇去訪問這些鏈接，結果失望地發現它只是指向一個外部鏈接。你可以使用任何 URL 去短網址服務，例如 unshorten.it，在訪問真正鏈接之前，查看它會指向哪裏。或者，你只需在 bit.ly 鏈接的末尾輸入加號（<code>+</code>）即可查看它們的實際位置以及有關鏈接的一些統計信息。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/shortlink.png" alt=""></p><h3 id="什麼是-motd-以及它是如何工作的" tabindex="-1">什麼是 MOTD 以及它是如何工作的？ <a class="header-anchor" href="#什麼是-motd-以及它是如何工作的" aria-label="Permalink to “什麼是 MOTD 以及它是如何工作的？”">​</a></h3><p>2009 年，來自 Canonical 的 Dustin Kirkland 在 Ubuntu 中引入了 MOTD 的概念。它是一個靈活的框架，使管理員或發行包能夠在 <code>/etc/update-motd.d/</code> 位置添加可執行腳本，目的是生成在登錄時顯示有益的、有趣的消息。它最初是為 Landscape（Canonical 的商業服務）實現的，但是其它發行版維護者發現它很有用，並且在他們自己的發行版中也採用了這個特性。</p><p>如果你在 Ubuntu 系統中查看 <code>/etc/update-motd.d/</code>，你會看到一組腳本。一個是打印通用的 “歡迎” 橫幅。下一個打印 3 個鏈接，顯示在哪裏可以找到操作系統的幫助。另一個計算並顯示本地系統包可以更新的數量。另一個腳本告訴你是否需要重新啓動等等。</p><p>從 Ubuntu 17.04 起，開發人員添加了 <code>/etc/update-motd.d/50-motd-news</code>，這是一個腳本用來在歡迎消息中包含一些附加信息。這些附加信息是：</p><ol><li>重要的關鍵信息，例如 ShellShock、Heartbleed 等</li><li>生命週期（EOL）消息，新功能可用性等</li><li>在 Ubuntu 官方Blog和其他有關 Ubuntu 的新聞中發佈的一些有趣且有益的帖子</li></ol><p>另一個特點是異步，啓動後約 60 秒，systemd 計時器運行 <code>/etc/update-motd.d/50-motd-news –force</code> 腳本。它提供了 <code>/etc/default/motd-news</code> 腳本中定義的 3 個配置變量。默認值為：<code>ENABLED=1, URLS=&quot;https://motd.ubuntu.com&quot;, WAIT=&quot;5&quot;</code>。</p><p>以下是 <code>/etc/default/motd-news</code> 文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/default/motd-news</span></span>
<span class="line"><span># Enable/disable the dynamic MOTD news service</span></span>
<span class="line"><span># This is a useful way to provide dynamic, informative</span></span>
<span class="line"><span># information pertinent to the users and administrators</span></span>
<span class="line"><span># of the local system</span></span>
<span class="line"><span>ENABLED=1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Configure the source of dynamic MOTD news</span></span>
<span class="line"><span># White space separated list of 0 to many news services</span></span>
<span class="line"><span># For security reasons, these must be https</span></span>
<span class="line"><span># and have a valid certificate</span></span>
<span class="line"><span># Canonical runs a service at motd.ubuntu.com, and you</span></span>
<span class="line"><span># can easily run one too</span></span>
<span class="line"><span>URLS=&quot;https://motd.ubuntu.com&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Specify the time in seconds, you&#39;re willing to wait for</span></span>
<span class="line"><span># dynamic MOTD news</span></span>
<span class="line"><span># Note that news messages are fetched in the background by</span></span>
<span class="line"><span># a systemd timer, so this should never block boot or login</span></span>
<span class="line"><span>WAIT=5</span></span></code></pre></div><p>好事情是 MOTD 是完全可定製的，所以你可以徹底禁用它（<code>ENABLED=0</code>）、根據你的意願更改或添加腳本、以秒為單位更改等待時間等等。</p><p>如果啓用了 MOTD，那麼 systemd 計時器作業將循環遍歷每個 URL，將它們的內容縮減到每行 80 個字符、最多 10 行，並將它們連接到 <code>/var/cache/motd-news</code> 中的緩存文件。此 systemd 計時器作業將每隔 12 小時運行並更新 <code>/var/cache/motd-news</code>。用户登錄後，<code>/var/cache/motd-news</code> 的內容會打印到屏幕上。這就是 MOTD 的工作原理。</p><p>此外，<code>/etc/update-motd.d/50-motd-news</code> 文件中包含自定義的用户代理字符串，以報告有關計算機的信息。如果你查看 <code>/etc/update-motd.d/50-motd-news</code> 文件，你會看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Piece together the user agent</span></span>
<span class="line"><span>USER_AGENT=&quot;curl/$curl_ver $lsb $platform $cpu $uptime&quot;</span></span></code></pre></div><p>這意味着，MOTD 檢索器將向 Canonical 報告你的操作系統版本、硬件平台、CPU 類型和正常運行時間。</p><p>到這裏，希望你對 MOTD 有了一個基本的瞭解。</p><p>現在讓我們回到主題，我不想要這個功能。我該如何禁用它？如果歡迎消息中的促銷鏈接仍然困擾你，並且你想永久禁用它們，則可以通過以下方法快速禁用它。</p><h3 id="在-ubuntu-服務器中禁用終端歡迎消息中的廣告" tabindex="-1">在 Ubuntu 服務器中禁用終端歡迎消息中的廣告 <a class="header-anchor" href="#在-ubuntu-服務器中禁用終端歡迎消息中的廣告" aria-label="Permalink to “在 Ubuntu 服務器中禁用終端歡迎消息中的廣告”">​</a></h3><p>要禁用這些廣告，編輯文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/default/motd-news</span></span></code></pre></div><p>找到以下行並將其值設置為 <code>0</code>（零）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[...]</span></span>
<span class="line"><span>ENABLED=0</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>保存並關閉文件。現在，重新啓動系統，看看歡迎消息是否仍然顯示來自 Ubuntu Blog的鏈接。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/Ubuntu-Terminal-welcome-message-1.png" alt=""></p><p>看到沒？現在沒有來自 Ubuntu Blog和 Ubuntu wiki 的鏈接。</p><p>這就是全部內容了。希望這對你有所幫助。更多好東西要來了，敬請關注！</p><p>順祝時祺！</p><hr>`,28)),i("p",null,[s[6]||(s[6]=n("via: ",-1)),t(e,{href:"https://www.ostechnix.com/how-to-disable-ads-in-terminal-welcome-message-in-ubuntu-server/"},{default:a(()=>[...s[5]||(s[5]=[n("https://www.ostechnix.com/how-to-disable-ads-in-terminal-welcome-message-in-ubuntu-server/",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=n("作者：",-1)),t(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[7]||(s[7]=[n("SK",-1)])]),_:1}),s[12]||(s[12]=n(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[8]||(s[8]=[n("lujun9972",-1)])]),_:1}),s[13]||(s[13]=n(" 譯者：",-1)),t(e,{href:"https://github.com/MjSeven"},{default:a(()=>[...s[9]||(s[9]=[n("MjSeven",-1)])]),_:1}),s[14]||(s[14]=n(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[10]||(s[10]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[16]||(s[16]=[n("Linux中國",-1)])]),_:1}),s[19]||(s[19]=n(" 榮譽推出",-1))])])}const U=p(r,[["render",c]]);export{k as __pageData,U as default};
